select

from sh_idle_item
where (idle_name LIKE "%"#{findValue}"%" or idle_details LIKE "%"#{findValue}"%" or idle_tags LIKE "%"#{findValue}"%") and idle_status = 1 order by id desc limit #{begin}, #{nums}

select

from sh_idle_item

  idle_status = 1

    and (idle_name LIKE "%"#{findValue}"%" or idle_details LIKE "%"#{findValue}"%" or idle_tags LIKE "%"#{findValue}"%")


    and idle_label = #{labelId}


    and idle_price >= #{minPrice}


    and idle_price <= #{maxPrice}


order by id desc limit #{begin}, #{nums}

select

from sh_idle_item
where idle_label = #{idleLabel}  and idle_status = 1 order by id desc limit #{begin}, #{nums}

select

from sh_idle_item
where idle_status = #{status} order by id desc limit #{begin}, #{nums}

