idle_name = #{idleName,jdbcType=VARCHAR}, idle_details = #{idleDetails,jdbcType=VARCHAR}, picture_list = #{pictureList,jdbcType=VARCHAR}, idle_price = #{idlePrice,jdbcType=DECIMAL}, idle_place = #{idlePlace,jdbcType=VARCHAR}, idle_label = #{idleLabel,jdbcType=INTEGER}, idle_tags = #{idleTags,jdbcType=VARCHAR}, idle_reason = #{idleReason,jdbcType=VARCHAR}, release_time = #{releaseTime,jdbcType=TIMESTAMP}, idle_status = #{idleStatus,jdbcType=TINYINT}, stock = #{stock,jdbcType=INTEGER},
where id = #{id,jdbcType=INTEGER} and user_id = #{userId,jdbcType=INTEGER}

update sh_idle_item
set idle_status = #{toStatus,jdbcType=TINYINT}
where id = #{id,jdbcType=INTEGER} and idle_status = #{fromStatus,jdbcType=TINYINT}

update sh_idle_item
set stock = stock + 1
where id = #{id,jdbcType=INTEGER}

update sh_idle_item
set sales_count = sales_count + 1
where id = #{id,jdbcType=INTEGER}

